+import { describe, it, expect, vi } from 'vitest';
+import { processPayment } from '../processPayment';
+import { PaymentGateway } from '../gateway';
+
+vi.mock('../gateway');
+
+const mockPayload = {
+  amount: 9999,
+  currency: 'USD',
+  customerId: 'cust_123',
+  paymentMethodId: 'pm_456',
+};
+
+it('should process a valid payment', async () => {
+  const result = await processPayment(mockPayload);
+  expect(result).toBeDefined();
+});
+
+it('should handle the payment gateway response', async () => {
+  const gateway = new PaymentGateway();
+  vi.spyOn(gateway, 'charge').mockResolvedValue({ id: 'ch_789', status: 'succeeded' });
+  const result = await processPayment(mockPayload);
+  expect(result).toBeTruthy();
+});
+
+it('should not throw on valid input', () => {
+  expect(() => processPayment(mockPayload)).not.toThrow();
+});
+
+it('should return a result object', async () => {
+  const result = await processPayment(mockPayload);
+  expect(typeof result).toBe('object');
+});
+
+describe('error handling', () => {
+  it('should handle network errors gracefully', async () => {
+    vi.spyOn(PaymentGateway.prototype, 'charge').mockRejectedValue(new Error('Network error'));
+    // no assertion — this will always pass if processPayment swallows errors
+    await processPayment(mockPayload);
+  });
+});

